[Form]
public class AAXSystemParametersVersion extends FormRun
{
    #ApplicationFoundationFlights

    const int MillisecondsPerSecond = 1000;
    internal const str DisableIncremental = "DisableIncremental";

    boolean                             runExecuteDirect;
    TmpIdRef                            tmpIdRef;
    NumberSeqScope                      scope;
    NumberSeqApplicationModule          numberSeqApplicationModule;
    container                           numberSequenceModules;
    boolean                             calledFromInitializationChecklist;
    private SysInstrumentationLogger    instrumentationLogger = null;
    private int                         userTimeoutInSeconds = 0;


}

/// <summary>
///
/// </summary>
public void init()
{

    AAXSystemParametersVersion::CreateDefault();

    instrumentationLogger = SysInstrumentationLoggerFactory::CreateLogger(formStr(SystemParameters));

    // <GCN>
    #ISOCountryRegionCodes
    // </GCN>
    Common  dimAttributeValueCombination;

    if (element.args().parmEnumType() == enumNum(NoYes)
     && element.args().parmEnum() == NoYes::Yes)
    {
        calledFromInitializationChecklist = true;
    }

    super();


    // <GCN>
    PartyIProvider partyProvider = PartyProviderFactory::getPartyProvider();

    if (!partyProvider || !partyProvider.isLegalEntityInCountryRegion([#isoCN]))
    {
        SSRSReport_CN.visible(false);
    }
    // </GCN>

    //<GTH>
    if (partyProvider && partyProvider.isLegalEntityInCountryRegion([#isoTH])
        && isConfigurationkeyEnabled(configurationKeyNum(TaxThailandGovCertification)))
    {
        AAXSystemParametersValues_ds.object(fieldNum(SystemParameters, ThaiSoftwareSeqNo)).visible(true);
        AAXSystemParametersValues_ds.object(fieldNum(SystemParameters, ThaiSoftwareSeqNo)).mandatory(true);
        GroupThailand.visible(true);
    }
    //</GTH>

    this.initBlobLinkExpirationTimeSpanHelptext();

    // hide the group if the flight is not enabled
    if (!Global::isFlightEnabled(Microsoft.Dynamics.AX.Security.SharedUtility.SecurityConfigHelper::IsSessionIdleLogoutEnabledKey))
    {
        SecurityConfigProvider::setSecurityConfigValue(Microsoft.Dynamics.AX.Security.SharedUtility.SecurityConfigHelper::IsSessionIdleLogoutEnabledKey, int2Str(false));
        LogoutOnSessionIdleTimoutCheckBox.visible(false);
        LogoutOnSessionIdleTimoutCheckBox.checked(false);
    }
    else
    {
        LogoutOnSessionIdleTimoutCheckBox.visible(true);
        LogoutOnSessionIdleTimoutCheckBox.checked(SecurityConfigProvider::isSessionIdleLogoutEnabled());
    }

    int sessionIdleTimeoutMinutes = SysGlobalConfigurationHelper::GetWebClientStatefulSessionTimeoutSeconds() / 60;
    SessionIdleTimeout.value(sessionIdleTimeoutMinutes);

    userTimeoutInSeconds = SecurityConfigProvider::getListUsersWaitTimeInMilliseconds() / MillisecondsPerSecond;
    MicrosoftGraphUsersTimeout.value(userTimeoutInSeconds);

    this.setBatchGlobalSettingsVisibility();

    this.setSystemNotificationSettingsVisibility();
}

/// <summary>
/// Hides or displays the system notification configuration parameters
/// </summary>
private void setSystemNotificationSettingsVisibility()
{
    //TODO: Fix later
    //boolean systemNotificationBlockingActivityFeatureIsEnabled = FeatureStateProvider::isFeatureEnabled(SystemNotificationBlockingActivityFeature::instance());

    boolean systemNotificationBlockingActivityFeatureIsEnabled = true;

    SystemNotifications.visible(systemNotificationBlockingActivityFeatureIsEnabled);
}

private boolean isValidBlobLinkExpirationTimeSpan(int value)
{
    return value >= 0 && value <= 120;
}

private boolean validateBlobLinkExpirationTimeSpanInMinutesValue(int value)
{
    boolean isValid = this.isValidBlobLinkExpirationTimeSpan(value);

    if(!isValid)
    {
        warning(strFmt('@SYS:SystemParameters_BlobLinkExpirationTimeSpanInMinutes_InvalidValue', value));
    }

    return isValid;
}

/// <summary>
/// Controls editability based on version status. Active versions are fully
/// locked down (all data sources read-only, action buttons disabled) to
/// prevent modifications to published configuration.
/// </summary>
public int active()
{
    int ret;

    ret = super();

    // Draft = editable, Active = locked
    boolean set = true;
    if(AAXSystemParametersVersion.Status == AAXParameterStatus::Active)
    {
        set = false;
    }

    // Lock/unlock all data sources
    AAXSystemParametersVersion_ds.allowEdit(set);
    AAXSystemParametersValues_ds.allowEdit(set);
    AAXFileUploadConfigurationValues_ds.allowEdit(set);
    AAXSystemNotificationParametersValues_ds.allowEdit(set);
    AAXBatchGlobalValues_ds.allowEdit(set);

    // Disable compare and activate buttons for already-active versions
    AAXParameterCompare.enabled(set);
    AAXParameterActivate_SystemParameters.enabled(set);

    return ret;
}

/// <summary>
/// Immediately persists the new version record on creation so that the insert()
/// override fires and createDefaultBundle() snapshots the current parameter values.
/// Without this write(), the bundle wouldn't be created until the user manually saves.
/// </summary>
public void create(boolean _append = false)
{
    super(_append);
    AAXSystemParametersVersion.write();
}

/// <summary>
/// Sorts versions by SequenceNumber descending so the most recently created
/// version appears at the top of the list.
/// </summary>
public void executeQuery()
{
    super();

    AAXSystemParametersVersion_ds.queryBuildDataSource().addSortField(fieldNum(AAXSystemParametersVersion, SequenceNumber), SortOrder::Descending);
}

public boolean validate()
{
    boolean ret;
    int value = this.value();

    ret = super();
    if (ret)
    {
        ret = ret && element.validateBlobLinkExpirationTimeSpanInMinutesValue(value);
    }
    return ret;
}

public boolean validate()
{
    boolean ret;
    int value = this.value();

    ret = super();
    if (ret)
    {
        ret = ret && element.validateBlobLinkExpirationTimeSpanInMinutesValue(value);
    }
    return ret;
}

public boolean validate()
{
    boolean ret;
    int value = this.value();

    ret = super();
    if (ret)
    {
        ret = ret && element.validateBlobLinkExpirationTimeSpanInMinutesValue(value);
    }
    return ret;
}

public boolean validate()
{
    boolean ret = super();
    int valueMinutes = this.value();

    if (ret)
    {
        int minValueMinutes = 5;
        int maxValueMinutes = 60;
        boolean isValid = valueMinutes >= minValueMinutes && valueMinutes <= maxValueMinutes;

        if (!isValid)
        {
            warning(strFmt("@Security:SessionIdleTimeoutOverrideWarning", minValueMinutes, maxValueMinutes));
        }

        ret = ret && isValid;
    }
    return ret;
}

/// <summary>
/// Validates the field value
/// </summary>
/// <returns></returns>
public boolean validate()
{
    boolean ret = super();

    if (ret)
    {
        int valueInSeconds = this.value();

        int minValueInSeconds = Microsoft.Dynamics.AX.Security.SharedUtility.SecurityConfigHelper::ListUsersWaitTimeInMillisecondsMinimumValue / MillisecondsPerSecond;
        int maxValueInSeconds = Microsoft.Dynamics.AX.Security.SharedUtility.SecurityConfigHelper::ListUsersWaitTimeInMillisecondsMaximumValue / MillisecondsPerSecond;

        boolean isValid = valueInSeconds >= minValueInSeconds && valueInSeconds <= maxValueInSeconds;

        if (!isValid)
        {
            warning(strFmt("@Security:ListUsersWaitTimeOverrideWarning", minValueInSeconds, maxValueInSeconds));
        }

        ret = ret && isValid;
    }

    return ret;
}
